window.ScripturaLexicons.LSJ.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2211\" data-lsj-orig-id=\"n2211\" data-lsj-ordinal=\"2251\"><td class=\"greek\">αἰγόφθαλμος</td><td>LSJ</td><td>«Olho de cabra», pedra preciosa.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2212\" data-lsj-orig-id=\"n2212\" data-lsj-ordinal=\"2252\"><td class=\"greek\">αἰγυπιός</td><td>LSJ</td><td>Abutre, ave de rapina.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2213\" data-lsj-orig-id=\"n2213\" data-lsj-ordinal=\"2253\"><td class=\"greek\">αἰγυπτάριον</td><td>LSJ</td><td>Nome de colírio.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2214\" data-lsj-orig-id=\"n2214\" data-lsj-ordinal=\"2254\"><td class=\"greek\">Αἰγύπτειος</td><td>LSJ</td><td>Egípcio, equivalente a Αἰγύπτιος; leitura provável.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2215\" data-lsj-orig-id=\"n2215\" data-lsj-ordinal=\"2255\"><td class=\"greek\">αἰγύπτης</td><td>LSJ</td><td>Glosa relacionada a σύντης e καλοβότης; significado não explicado autonomamente.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2216\" data-lsj-orig-id=\"n2216\" data-lsj-ordinal=\"2256\"><td class=\"greek\">Αἰγυπτιάζω</td><td>LSJ</td><td>Imitar egípcios, às vezes no sentido pejorativo antigo de agir astuciosamente; falar egípcio; ficar inundado, como o Egito.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2217\" data-lsj-orig-id=\"n2217\" data-lsj-ordinal=\"2257\"><td class=\"greek\">Αἰγυπτιακός</td><td>LSJ</td><td>Relativo ao Egito, egípcio; título de obras sobre o Egito.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2218\" data-lsj-orig-id=\"n2218\" data-lsj-ordinal=\"2258\"><td class=\"greek\">Αἰγυπτιασμός</td><td>LSJ</td><td>Imitação das práticas egípcias.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2219\" data-lsj-orig-id=\"n2219\" data-lsj-ordinal=\"2259\"><td class=\"greek\">Αἰγύπτιος</td><td>LSJ</td><td>Egípcio, do Egito; em estilo egípcio; nome feminino de unguento.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2220\" data-lsj-orig-id=\"n2220\" data-lsj-ordinal=\"2260\"><td class=\"greek\">Αἰγυπτιόω</td><td>LSJ</td><td>Tornar a pele semelhante à atribuída aos egípcios na fonte antiga, escurecer a tez.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2221\" data-lsj-orig-id=\"n2221\" data-lsj-ordinal=\"2261\"><td class=\"greek\">Αἰγυπτιστί</td><td>LSJ</td><td>Na língua egípcia; à maneira egípcia, às vezes «astutamente».</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2222\" data-lsj-orig-id=\"n2222\" data-lsj-ordinal=\"2262\"><td class=\"greek\">Αἰγυπτιώδης</td><td>LSJ</td><td>Semelhante aos egípcios.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2223\" data-lsj-orig-id=\"n2223\" data-lsj-ordinal=\"2263\"><td class=\"greek\">Αἰγυπτογενής</td><td>LSJ</td><td>De origem egípcia.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2224\" data-lsj-orig-id=\"n2224\" data-lsj-ordinal=\"2264\"><td class=\"greek\">Αἴγυπτος</td><td>LSJ</td><td>Egito, país; em outros usos, rio Nilo ou o rei mítico Egipto.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2225\" data-lsj-orig-id=\"n2225\" data-lsj-ordinal=\"2265\"><td class=\"greek\">αἰγωγαίαν</td><td>LSJ</td><td>Olho; glosa ὀφθαλμός.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2226\" data-lsj-orig-id=\"n2226\" data-lsj-ordinal=\"2266\"><td class=\"greek\">αἰγωλιός</td><td>LSJ</td><td>Pequena coruja, talvez Strix flammea; identificação incerta.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2227\" data-lsj-orig-id=\"n2227\" data-lsj-ordinal=\"2267\"><td class=\"greek\">αἰγών</td><td>LSJ</td><td>Aprisco, curral; também nome de mês em Alexandria.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2228\" data-lsj-orig-id=\"n2228\" data-lsj-ordinal=\"2268\"><td class=\"greek\">αἰγῶνυξ</td><td>LSJ</td><td>Com cascos de cabra.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2229\" data-lsj-orig-id=\"n2229\" data-lsj-ordinal=\"2269\"><td class=\"greek\">αἰγωπόμματος</td><td>LSJ</td><td>Equivalente ao artigo seguinte, αἰγωπός.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2230\" data-lsj-orig-id=\"n2230\" data-lsj-ordinal=\"2270\"><td class=\"greek\">αἰγωπός</td><td>LSJ</td><td>De olhos como os de uma cabra.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2231\" data-lsj-orig-id=\"n2231\" data-lsj-ordinal=\"2271\"><td class=\"greek\">αἰδάας</td><td>LSJ</td><td>Senhor, amo; glosa δεσπότης.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2232\" data-lsj-orig-id=\"n2232\" data-lsj-ordinal=\"2272\"><td class=\"greek\">αἰδάνης</td><td>LSJ</td><td>Que passa o tempo ou permanece ocupado; glosa tarentina διατρίβων.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2233\" data-lsj-orig-id=\"n2233\" data-lsj-ordinal=\"2273\"><td class=\"greek\">Ἀΐδας</td><td>LSJ</td><td>Forma dórica de Ἀΐδης, Hades.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2234\" data-lsj-orig-id=\"n2234\" data-lsj-ordinal=\"2274\"><td class=\"greek\">αἰδέομαι</td><td>LSJ</td><td>Sentir vergonha ou pudor; respeitar e reverenciar; temer respeitosamente; compadecer-se, ter misericórdia; reconciliar-se, obter perdão.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2234a\" data-lsj-orig-id=\"n2234a\" data-lsj-ordinal=\"2275\"><td class=\"greek\">αἰδέσιμος</td><td>LSJ</td><td>Que provoca pudor e respeito, venerável; sagrado; reverentemente, em uso adverbial.</td><td>LSJ</td></tr>";
